import { describe, expect, it } from 'vitest';

import { getNextVersion } from './get-next-package-version';

describe('getNextVersion (lib)', () => {
  it('hotfix increments patch', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.1',
        type: 'hotfix',
        currentDate: new Date('2025-08-10'),
      }),
    ).toBe('25.8.2');
  });

  it('monthly advances month same year', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.3',
        type: 'monthly',
        currentDate: new Date('2025-08-15'),
      }),
    ).toBe('25.9.0');
  });

  it('monthly wraps year December -> January', () => {
    expect(
      getNextVersion({
        currentVersion: '25.12.3',
        type: 'monthly',
        currentDate: new Date('2025-12-05'),
      }),
    ).toBe('26.1.0');
  });

  it('nightly format with date stamp', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.1',
        type: 'nightly',
        currentDate: new Date('2025-08-22'),
      }),
    ).toBe('25.9.0-nightly.20250822');
  });

  it('auto before 25th -> hotfix', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.4',
        type: 'auto',
        currentDate: new Date('2025-08-20'),
      }),
    ).toBe('25.8.5');
  });

  it('auto after 25th (same month) -> monthly', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.4',
        type: 'auto',
        currentDate: new Date('2025-08-27'),
      }),
    ).toBe('25.9.0');
  });

  it('auto after 25th (next month) -> monthly', () => {
    expect(
      getNextVersion({
        currentVersion: '25.8.4',
        type: 'auto',
        currentDate: new Date('2025-09-02'),
      }),
    ).toBe('25.9.0');
  });

  it('invalid type throws', () => {
    expect(() =>
      getNextVersion({
        currentVersion: '25.8.4',
        type: 'unknown' as never,
        currentDate: new Date('2025-08-10'),
      }),
    ).toThrow(/Invalid type/);
  });
});

import { describe, expect, it, vi } from 'vitest';

import { resolveBuildRun } from './resolve.mjs';

describe('resolveBuildRun', () => {
  it('selects the exact commit and rejects a stale API result', async () => {
    const expectedSha = 'adf5d198282218f06ce0a6cbe847bee66f483332';
    const staleRun = {
      id: 30768952310,
      head_sha: '4e5c0d5f87f1c4277b12a1811023a03db9ccb4b8',
      html_url:
        'https://github.com/actualbudget/actual/actions/runs/30768952310',
    };
    const expectedRun = {
      id: 32157684269,
      head_sha: expectedSha,
      html_url:
        'https://github.com/actualbudget/actual/actions/runs/32157684269',
    };
    const listWorkflowRuns = vi.fn().mockResolvedValue({
      data: { workflow_runs: [staleRun, expectedRun] },
    });
    const sleep = vi.fn();

    const run = await resolveBuildRun({
      github: { rest: { actions: { listWorkflowRuns } } },
      owner: 'actualbudget',
      repo: 'actual',
      headSha: expectedSha,
      label: 'master base',
      notFoundHint: 'master may be broken',
      timeoutMs: 1_000,
      sleep,
    });

    expect(run).toBe(expectedRun);
    expect(listWorkflowRuns).toHaveBeenCalledOnce();
    expect(listWorkflowRuns).toHaveBeenCalledWith({
      owner: 'actualbudget',
      repo: 'actual',
      workflow_id: 'build.yml',
      head_sha: expectedSha,
      status: 'success',
      per_page: 20,
    });
    expect(listWorkflowRuns.mock.calls[0][0]).not.toHaveProperty('branch');
    expect(sleep).not.toHaveBeenCalled();
  });

  it('fails when no successful run exists for the commit', async () => {
    const listWorkflowRuns = vi
      .fn()
      .mockResolvedValue({ data: { workflow_runs: [] } });
    const now = vi.fn().mockReturnValueOnce(0).mockReturnValue(11);

    await expect(
      resolveBuildRun({
        github: { rest: { actions: { listWorkflowRuns } } },
        owner: 'actualbudget',
        repo: 'actual',
        headSha: 'base-sha',
        label: 'master base',
        notFoundHint: 'master may be broken',
        timeoutMs: 10,
        now,
      }),
    ).rejects.toThrow(/No successful build\.yml run found for master base/);
  });
});

import { describe, expect, it } from 'vitest';

import {
  absolutizeLinks,
  buildNewsFeed,
  getPostSlug,
  parsePost,
  stripHtmlComments,
} from './parse';
import type { NewsEntry } from './parse';

const siteUrl = 'https://actualbudget.org';

describe('stripHtmlComments', () => {
  it('removes comments, including nested or overlapping markers', () => {
    expect(stripHtmlComments('a <!-- x --> b')).toBe('a  b');
    expect(stripHtmlComments('a <!-<!---->-> b')).toBe('a  b');
    expect(stripHtmlComments('<!--<!-- x -->-->')).toBe('-->');
    expect(stripHtmlComments('a <!-- unterminated')).toBe('a ');
    expect(stripHtmlComments('no comments')).toBe('no comments');
  });
});

describe('absolutizeLinks', () => {
  it('resolves relative and root-relative links and leaves absolute ones', () => {
    const input =
      '[a](../../docs/transactions/payee-locations) [b](/docs/reports/) [c](https://example.com) [d](#anchor) ![img](./img/x.png) [e](//example.com/page) [f](mailto:hi@example.com)';
    expect(absolutizeLinks(input, siteUrl, '/blog/')).toBe(
      '[a](https://actualbudget.org/docs/transactions/payee-locations) [b](https://actualbudget.org/docs/reports) [c](https://example.com) [d](#anchor) ![img](https://actualbudget.org/blog/img/x.png) [e](//example.com/page) [f](mailto:hi@example.com)',
    );
  });

  it('leaves links it cannot parse alone and warns', () => {
    const warnings: string[] = [];
    expect(
      // Two backslashes resolve like `//` but aren't caught by the
      // protocol-relative check, giving an invalid host that throws.
      absolutizeLinks('[x](\\\\[)', siteUrl, '/blog/', message =>
        warnings.push(message),
      ),
    ).toBe('[x](\\\\[)');
    expect(warnings).toEqual(['Leaving unparseable link "\\\\[" as-is']);
  });
});

describe('parsePost', () => {
  describe('release posts', () => {
    const releasePost = `---
title: Release 26.8.0
description: New release of Actual.
date: 2026-08-02T10:00
slug: release-26.8.0
tags: [announcement, release]
in_app_notification: true
authors: matt-fidd
---

This release promotes [Payee Locations](../../docs/transactions/payee-locations) to stable.

- Age of Money report released
- Day-level date ranges in [reports](/docs/reports/)

<!--truncate-->

**Docker Tag: 26.8.0**

<!-- release-notes:auto-generated -->

#### Features

- [#8540](https://github.com/actualbudget/actual/pull/8540) Promote Age of Money — thanks @youngcw
`;

    it('splits highlights from the categorized changes', () => {
      const entry = parsePost('2026-08-02-release-26-8-0.md', releasePost, {
        siteUrl,
      });

      expect(entry).toMatchObject({
        id: 'release-26.8.0',
        type: 'release',
        title: 'Release 26.8.0',
        date: '2026-08-02',
        version: '26.8.0',
        url: 'https://actualbudget.org/blog/release-26.8.0',
      });
      expect(entry?.body).toBe(
        `This release promotes [Payee Locations](https://actualbudget.org/docs/transactions/payee-locations) to stable.

- Age of Money report released
- Day-level date ranges in [reports](https://actualbudget.org/docs/reports)`,
      );
      expect(entry?.details).toBe(
        `#### Features

- [#8540](https://github.com/actualbudget/actual/pull/8540) Promote Age of Money — thanks @youngcw`,
      );
      expect(entry?.body).not.toContain('Docker Tag');
      expect(entry?.details).not.toContain('Docker Tag');
      expect(entry?.details).not.toContain('release-notes:auto-generated');
    });

    it('handles older posts without the auto-generated marker', () => {
      const entry = parsePost(
        '2026-05-08-release-26-5-1.md',
        `---
title: Release 26.5.1 & 26.5.2
date: 2026-05-08T10:00
slug: release-26.5.1
tags: [announcement, release]
in_app_notification: true
---

This patch release delivers bugfixes.

**Docker Tag: 26.5.1 / 26.5.2**

#### Bugfixes

- [#7707](https://github.com/actualbudget/actual/pull/7707) Count only failed logins — thanks @danielhopkins
`,
        { siteUrl },
      );

      expect(entry).toMatchObject({
        id: 'release-26.5.1',
        title: 'Release 26.5.1 & 26.5.2',
        version: '26.5.1',
        body: 'This patch release delivers bugfixes.',
      });
      expect(entry?.details).toContain('#7707');
    });

    it('fails on release posts with an unexpected slug', () => {
      expect(() =>
        parsePost(
          '2026-08-02-release-26-8-0.md',
          releasePost.replace('slug: release-26.8.0', 'slug: big-release'),
          { siteUrl },
        ),
      ).toThrow(
        'Release post "2026-08-02-release-26-8-0.md" has an unexpected slug "big-release"',
      );
    });
  });

  describe('other posts', () => {
    const post = `---
title: 'Design Competition: Reimagine the Sidenav'
description: The sidenav is getting some love.
date: 2026-06-27T10:00
slug: design-competition-sidenav
tags: [announcement]
in_app_notification: true
authors: MatissJanis
---

Intro paragraph with a [link](./2026-08-05-sidenav-voting-open.md) and [docs](/docs/settings).

<!--truncate-->

## Details

More text.
`;

    it('parses front matter, rewrites links and strips the truncate marker', () => {
      const entry = parsePost(
        '2026-07-27-design-competition-sidenav.md',
        post,
        {
          siteUrl,
          postSlugs: new Map([
            [
              '2026-07-27-design-competition-sidenav.md',
              'design-competition-sidenav',
            ],
            ['2026-08-05-sidenav-voting-open.md', 'sidenav-voting-open'],
          ]),
        },
      );

      expect(entry).toMatchObject({
        id: 'post-design-competition-sidenav',
        type: 'post',
        title: 'Design Competition: Reimagine the Sidenav',
        date: '2026-06-27',
        url: 'https://actualbudget.org/blog/design-competition-sidenav',
      });
      expect(entry?.body).not.toContain('truncate');
      expect(entry?.body).toContain(
        '[link](https://actualbudget.org/blog/sidenav-voting-open)',
      );
      expect(entry?.body).toContain(
        '[docs](https://actualbudget.org/docs/settings)',
      );
    });

    it('resolves links to posts that use a custom slug', () => {
      const target = `---
title: Automate
slug: 2023-12-15-automate-your-budget-with-goal-templates
---
x`;
      const postSlugs = new Map([
        [
          '2023-12-15-automate.md',
          getPostSlug('2023-12-15-automate.md', target),
        ],
        ['2024-03-25-twist.md', 'twist'],
      ]);
      const entry = parsePost(
        '2024-03-25-twist.md',
        `---
title: Twist
in_app_notification: true
---

Start [here](./2023-12-15-automate.md#month-ahead).
`,
        { siteUrl, postSlugs },
      );
      expect(entry?.body).toBe(
        'Start [here](https://actualbudget.org/blog/2023-12-15-automate-your-budget-with-goal-templates#month-ahead).',
      );
    });

    it('drops a leading H1 that duplicates the title', () => {
      const entry = parsePost(
        '2026-01-17-next-steps.md',
        `---
title: Next Steps
in_app_notification: true
---

# Next Steps

Intro.

## Later heading

# Not a leading heading
`,
        { siteUrl },
      );
      expect(entry?.body).toBe(
        'Intro.\n\n## Later heading\n\n# Not a leading heading',
      );
    });

    it('falls back to the filename for the date and slug', () => {
      const entry = parsePost(
        '2024-03-25-automate-twist.md',
        `---
title: Automate
in_app_notification: true
---

Body text.
`,
        { siteUrl },
      );
      expect(entry).toMatchObject({
        id: 'post-automate-twist',
        date: '2024-03-25',
        url: 'https://actualbudget.org/blog/automate-twist',
        body: 'Body text.',
      });
    });

    it('skips posts that are not marked for the app', () => {
      expect(
        parsePost(
          '2026-08-08-unmarked.md',
          `---
title: Unmarked
---
x`,
          { siteUrl },
        ),
      ).toBeUndefined();
      expect(
        parsePost(
          '2026-08-08-opted-out.md',
          `---
title: Opted out
in_app_notification: false
---
x`,
          { siteUrl },
        ),
      ).toBeUndefined();
    });

    it('skips drafts and fails on undated posts', () => {
      expect(
        parsePost(
          '2026-08-08-something.md',
          `---
title: Draft
draft: true
in_app_notification: true
---
x`,
          { siteUrl },
        ),
      ).toBeUndefined();
      expect(() =>
        parsePost(
          'welcome.md',
          `---
title: Welcome
in_app_notification: true
---
x`,
          { siteUrl },
        ),
      ).toThrow('Post "welcome.md" is marked for the app but has no date');
    });
  });
});

describe('buildNewsFeed', () => {
  function release(version: string, date: string): NewsEntry {
    return {
      id: `release-${version}`,
      type: 'release',
      title: `Release ${version}`,
      date,
      version,
      url: '',
      body: '',
    };
  }
  function post(slug: string, date: string): NewsEntry {
    return {
      id: `post-${slug}`,
      type: 'post',
      title: slug,
      date,
      url: '',
      body: '',
    };
  }

  it('sorts newest first and caps releases and posts separately', () => {
    const feed = buildNewsFeed({
      entries: [
        post('b', '2026-02-15'),
        release('1.0.0', '2026-01-01'),
        release('3.0.0', '2026-03-01'),
        post('a', '2026-03-01'),
        release('2.0.0', '2026-02-01'),
      ],
      releaseLimit: 2,
      postLimit: 1,
    });

    expect(feed.schemaVersion).toBe(1);
    expect(feed.entries.map(entry => entry.id)).toEqual([
      'release-3.0.0',
      'post-a',
      'release-2.0.0',
    ]);
  });
});

import { describe, expect, it } from 'vitest';

import {
  findAddedMigrations,
  findMisdatedMigrations,
  findMutatedMigrations,
  findRiskyStatements,
  parseMigrationTree,
} from './check';

const treeOutput = [
  '100644 blob aaa111\tpackages/loot-core/migrations/1000_first.sql',
  '100644 blob bbb222\tpackages/loot-core/migrations/2000_second.js',
  '100644 blob ccc333\tpackages/loot-core/migrations/.hidden',
].join('\n');

describe('parseMigrationTree', () => {
  it('parses names, ids, and hashes, skipping hidden files', () => {
    expect(parseMigrationTree(treeOutput)).toEqual([
      { name: '1000_first.sql', id: 1000, hash: 'aaa111' },
      { name: '2000_second.js', id: 2000, hash: 'bbb222' },
    ]);
  });

  it('returns an empty list for empty output', () => {
    expect(parseMigrationTree('')).toEqual([]);
  });
});

describe('findAddedMigrations', () => {
  it('returns migrations present on head but not on base', () => {
    const base = parseMigrationTree(treeOutput);
    const head = [
      ...base,
      { name: '3000_third.sql', id: 3000, hash: 'ddd444' },
    ];
    expect(findAddedMigrations(base, head)).toEqual([
      { name: '3000_third.sql', id: 3000, hash: 'ddd444' },
    ]);
  });
});

describe('findMutatedMigrations', () => {
  it('detects modified and deleted migrations', () => {
    const base = parseMigrationTree(treeOutput);
    const head = [{ name: '1000_first.sql', id: 1000, hash: 'changed' }];
    expect(findMutatedMigrations(base, head)).toEqual({
      modified: ['1000_first.sql'],
      deleted: ['2000_second.js'],
    });
  });

  it('reports nothing when head matches base', () => {
    const base = parseMigrationTree(treeOutput);
    expect(findMutatedMigrations(base, base)).toEqual({
      modified: [],
      deleted: [],
    });
  });
});

describe('findMisdatedMigrations', () => {
  it('flags migrations dated at or before the latest existing one', () => {
    const added = [
      { name: '1500_late.sql', id: 1500, hash: 'a' },
      { name: '2000_same.sql', id: 2000, hash: 'b' },
      { name: '2500_ok.sql', id: 2500, hash: 'c' },
    ];
    expect(findMisdatedMigrations(added, 2000).map(m => m.name)).toEqual([
      '1500_late.sql',
      '2000_same.sql',
    ]);
  });
});

describe('findRiskyStatements', () => {
  it('flags DROP TABLE, DROP COLUMN, and RENAME statements', () => {
    expect(findRiskyStatements('ALTER TABLE x DROP COLUMN y;')).toEqual([
      'drops a column',
    ]);
    expect(findRiskyStatements('DROP TABLE x;')).toEqual(['drops a table']);
    expect(findRiskyStatements('ALTER TABLE x RENAME TO y;')).toEqual([
      'renames a table or column',
    ]);
    expect(findRiskyStatements('ALTER TABLE x RENAME COLUMN a TO b;')).toEqual([
      'renames a table or column',
    ]);
  });

  it('ignores additive statements and comments', () => {
    expect(findRiskyStatements('ALTER TABLE x ADD COLUMN y TEXT;')).toEqual([]);
    expect(
      findRiskyStatements('-- do not DROP TABLE here\nCREATE TABLE y (id);'),
    ).toEqual([]);
    expect(
      findRiskyStatements('/* DROP COLUMN in a block comment */ SELECT 1;'),
    ).toEqual([]);
  });
});

